import { VERSION, DEFAULT_PROFILE, EXERCISES, BY_ID, LABELS, makePlan, isoLocalDate, summarize, validateImport, validateSession } from './core.mjs';
import { TRACKS, skillIndex, skillCompleted, stageAllowed, recordedSets, weeklyLoad, visualGuide } from './evolution.mjs';
import { DEFAULT_REMINDERS, normalizeReminders, AWARDS, gamification, calendarUrl, calendarIcs, inQuietTime } from './gamification.mjs';
import { imagesHtml, remoteImages, matchCount, bjjDiagram } from './visuals.mjs';
import { TECHNIQUES, TECH_BY_ID, TECH_CATEGORIES, TECH_LEVELS, TECH_GI, TECH_STATUS, TROUBLE_SPOTS, SESSION_KINDS, videoSearchUrl, techniqueStatus, techniqueSummary, filterTechniques } from './techniques.mjs';
import { BELTS, IBJJF_MIN_MONTHS, DEFAULT_BELT_STATE, normalizeBelt, sortedPromotions, currentBelt, beltStats, formatDuration, bjjStats, monthSessions, techniqueHistory, techName } from './bjj.mjs';

const STORAGE_KEY='calistenia_bjj_v1';
const content=document.getElementById('content');
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(map,value)=>Object.entries(map).map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
const fmtDate=(v)=>{const d=new Date((v||isoLocalDate())+'T12:00:00');return Number.isNaN(d.valueOf())?esc(v):d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});};
const greeting=()=>new Date().getHours()<12?'Bom dia':new Date().getHours()<18?'Boa tarde':'Boa noite';
function freshState(){return {schema:VERSION,profile:{...DEFAULT_PROFILE},history:[],workout:null,skills:{},reminders:{...DEFAULT_REMINDERS},belt:normalizeBelt(),techniques:{}};}
let memoryOnly=false;
function load(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return freshState();const v=JSON.parse(raw);if(!validateImport(v))throw Error('Dados inválidos');return {...freshState(),...v,profile:{...DEFAULT_PROFILE,...v.profile},reminders:normalizeReminders(v.reminders),belt:normalizeBelt(v.belt),techniques:v.techniques||{}};}catch(err){memoryOnly=true;return freshState();}}
let state=load(),tab='inicio',search='',filter='todos',selectedExercise=null,exerciseReturn='exercicios',selectedTrack=null,installPrompt=null,toastTimer=null;
let libMode='tecnicas',techQuery='',techCat='todas',techStatusFilter='todos',selectedTech=null,techReturn='exercicios';
let diaryDraft={given:[],taken:[],worked:[]};
function currentPlan(){const plan=makePlan(state.profile);const load=weeklyLoad(state.history);if(load.high&&!plan.recovery){plan.days=plan.days.slice(0,2);plan.why+=' Foram registrados vários treinos de BJJ nesta semana: considere reduzir volume e inserir recuperação.';}return plan;}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));memoryOnly=false;return true;}catch(err){memoryOnly=true;notify('Sem armazenamento local. Exporte um backup antes de sair.');return false;}}
function notify(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3900);}
function go(next){tab=next;selectedExercise=null;selectedTech=null;render();window.scrollTo({top:0,behavior:'instant'});}
function header(eyebrow,title,subtitle=''){return `<header class="top-section"><div class="eyebrow">${esc(eyebrow)}</div><h1 class="headline">${title}</h1>${subtitle?`<p class="lead">${subtitle}</p>`:''}</header>`;}
function section(title,body,classes=''){return `<section class="card ${classes}"><h2 class="section-title">${title}</h2>${body}</section>`;}
function chip(value){return `<span class="chip">${esc(value)}</span>`;}
function tagCat(ex){return LABELS.category[ex.category]||ex.category;}
function exIcon(ex){return ({aquecimento:'↗',forca:'◆',musculacao:'▰',mobilidade:'◌',drill:'◎',condicionamento:'◷',recuperacao:'☾'})[ex.category]||'◈';}
function exRow(ex,withButton=true){const media=remoteImages(ex);return `<div class="exercise"><div class="exicon">${media?`<img loading="lazy" src="${media.photos[0]}" alt="" onerror="this.hidden=true" />`:exIcon(ex)}</div><div class="exbody"><h3>${esc(ex.name)}</h3><p>${esc(tagCat(ex))} · ${ex.sets} ${ex.sets===1?'série':'séries'} · ${esc(ex.dose)} · ${esc(LABELS.gear[ex.gear])}</p><div class="row wrap">${withButton?`<button class="linklike" data-action="exercise" data-id="${ex.id}">Ver execução e cuidados →</button>`:`<span class="small muted">${esc(ex.why)}</span>`}</div></div></div>`;}
function recent(days){const since=new Date();since.setHours(0,0,0,0);since.setDate(since.getDate()-(days-1));return state.history.filter(s=>{const d=new Date(s.date+'T12:00:00');return !Number.isNaN(d.valueOf()) && d>=since;});}
function currentTip(){if(state.profile.readiness<=1)return 'Energia muito baixa: priorize repouso; evite treinos intensos.';if(state.profile.readiness===2)return 'Energia reduzida: mobilidade opcional e recuperação; evite treinos pesados.';return 'Treine com controle: deixe dias de recuperação entre sessões intensas.';}
function latestHistory(limit=6){return [...state.history].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,limit).map(s=>`<div class="history-item"><div class="history-symbol">${s.type==='bjj'?'🥋':'◆'}</div><div class="meta"><h4>${s.type==='bjj'?'Jiu-jitsu':'Preparação física'} · ${esc(s.title||'Treino')}${s.kind&&SESSION_KINDS[s.kind]?' · '+esc(SESSION_KINDS[s.kind]):''}</h4><p>${fmtDate(s.date)} · ${Number(s.duration)||0} min ${s.type==='bjj'?`· ${Number(s.rounds)||0} rolas${s.given?.length||s.taken?.length?` · ✓${s.given?.length||0} ✗${s.taken?.length||0} finalizações`:''}`:''} · esforço ${esc(s.rpe||'—')}/10</p>${s.note?`<div class="small muted">${esc(s.note).slice(0,240)}</div>`:''}</div></div>`).join('')||'<div class="empty">Nenhum treino registrado ainda.</div>';}

function renderHome(){
 const week=recent(7),bjj=week.filter(s=>s.type==='bjj'),phys=week.filter(s=>s.type==='fisico');
 const pname=state.profile.name.trim().split(' ')[0]||'atleta';
 const load=weeklyLoad(state.history);
 const p=state.profile;
 return `${header('Seu espaço de evolução',`${greeting()}, <span>${esc(pname)}.</span>`,'Técnica, faixa e preparo físico do seu jiu-jitsu. Um passo de cada vez.')}
 <div class="grid">
  <div class="span-8"><section class="card hero"><span class="badge">SEU PRÓXIMO PASSO</span><h2>${p.readiness<=2?'Hoje, priorize a recuperação.':'Construa força que aparece no tatame.'}</h2><p>${p.readiness<=2?'O plano será ajustado para mobilidade leve e descanso.':'Treinos pensados para seu nível, equipamento e estilo de jogo, sem ignorar a recuperação.'}</p><div class="row wrap"><button class="btn" data-action="navigate" data-to="plano">Montar meu treino →</button><button class="btn secondary" data-action="navigate" data-to="diario">Registrar rola</button></div></section></div>
  <div class="span-4"><section class="card"><div class="eyebrow">Como está sua energia?</div><h2 class="card-title" style="margin-top:10px">Prontidão de hoje</h2><p class="small muted">Informe como se sente antes de treinar.</p><div class="field"><label for="readiness">Energia percebida: <strong id="readiness-text">${p.readiness}/5</strong></label><input id="readiness" type="range" min="1" max="5" step="1" value="${p.readiness}" aria-label="Energia de hoje" /></div><div class="note ${p.readiness<=2?'warn':''}" style="margin-top:15px" id="readiness-note">${currentTip()}</div></section></div>
  <div class="span-6">${beltCard()}</div><div class="span-6">${focusCard()}</div>
  <div class="span-4"><div class="stat"><div class="eyebrow">Últimos 7 dias</div><div class="kpi">${bjj.length}</div><div class="kpi-label">Treinos de jiu-jitsu</div></div></div>
  <div class="span-4"><div class="stat"><div class="eyebrow">Últimos 7 dias</div><div class="kpi">${phys.length}</div><div class="kpi-label">Sessões físicas</div></div></div>
  <div class="span-4"><div class="stat"><div class="eyebrow">Últimos 7 dias</div><div class="kpi">${week.reduce((sum,s)=>sum+Number(s.duration||0),0)}</div><div class="kpi-label">Minutos totais registrados</div></div></div>
  <div class="span-12">${gamificationCard()}</div>
 <div class="span-12">${section('Sua rotina',`<p class="small muted">Organize lembretes de exercícios pelo Google Agenda e avisos de hidratação enquanto o app estiver aberto.</p><button class="btn secondary small-btn" data-action="navigate" data-to="rotina">Configurar lembretes →</button>`)}</div>
 <div class="span-12">${section('Suas progressões',`<div class="row between wrap"><div><strong>${skillCompleted(state.skills)} etapas registradas</strong><p class="small muted">Seis trilhas para desenvolver força, quadril, pegada e controle.</p></div><button class="btn secondary small-btn" data-action="navigate" data-to="habilidades">Ver minhas habilidades →</button></div>`)}</div>
  <div class="span-7">${section('Seu perfil atual',`<div class="pill-row">${chip(LABELS.style[p.style])}${chip(LABELS.goal[p.goal])}${chip(LABELS.level[p.level])}${chip(LABELS.gear[p.equipment])}</div><p class="small muted">O plano é montado a partir destas informações. Você pode alterá-las quando quiser.</p><button class="btn secondary small-btn" data-action="navigate" data-to="ajustes">Ajustar meu perfil</button>`)}</div>
  <div class="span-5">${section('Histórico recente',latestHistory(3)+`<button class="btn ghost small-btn" data-action="navigate" data-to="evolucao" style="margin-top:12px">Ver evolução →</button>`)}</div>
 </div>${load.high?`<div class="note warn" style="margin-top:14px">Nos últimos 7 dias: ${load.bjj} treinos de BJJ, ${load.minutes} minutos, ${load.hard} intensos (RPE 8–10). Seu plano sugere no máximo duas sessões físicas; ajuste com orientação.</div>`:``}<p class="small muted" style="margin-top:18px">Atenção: fadiga incomum, dor intensa, falta de ar ou tontura exigem interromper o exercício e avaliar a situação. O aplicativo não substitui avaliação profissional.</p>`;
}

function renderPlan(){
 if(state.workout)return renderWorkout();
 const p=state.profile, plan=currentPlan(), load=weeklyLoad(state.history);
 const dayCards=plan.days.map((d,i)=>`<div class="session-card"><div class="row between" style="align-items:flex-start"><div class="row"><div class="session-count">${String.fromCharCode(65+i)}</div><div><h3>${esc(d.title)}</h3><p class="small muted" style="margin:3px 0">${esc(d.subtitle)}</p></div></div><span class="badge ${plan.recovery?'orange':'gray'}">${d.items.length} exercícios</span></div><div class="divider"></div>${d.items.map(ex=>exRow(ex)).join('')}<button class="btn" data-action="startWorkout" data-index="${i}">${plan.recovery?'Registrar sessão leve':'Iniciar sessão'} →</button></div>`).join('');
 return `${header('Planejamento','Seu <span>plano de treino.</span>','Treinos indicativos, ajustados ao tipo de jogo, ao nível e aos recursos disponíveis.')}
 <div class="grid"><div class="span-4"><section class="card"><div class="eyebrow">Configuração</div><h2 class="card-title" style="margin-top:10px">${esc(LABELS.style[p.style])}</h2><p class="small muted">${esc(LABELS.goal[p.goal])} · ${esc(LABELS.level[p.level])}</p><div class="divider"></div><div class="stack small"><div class="row between"><span class="muted">Equipamentos</span><strong>${esc(LABELS.gear[p.equipment])}</strong></div><div class="row between"><span class="muted">Sessões sugeridas</span><strong>${plan.days.length}${plan.recovery?' leve':''}</strong></div><div class="row between"><span class="muted">Energia informada</span><strong>${p.readiness}/5</strong></div></div><div class="divider"></div><button class="btn secondary" data-action="navigate" data-to="ajustes">Editar perfil</button></section><div class="note ${plan.recovery?'warn':''}" style="margin-top:14px">${esc(plan.why)} ${p.caution?'Ativada a preferência de cautela para lombar/quadril.':''}</div></div>
 <div class="span-8">${load.high?`<div class="note warn">Carga de BJJ registrada como elevada pelos critérios simples do app (${load.bjj} aulas, ${load.minutes} min, ${load.hard} intensas em 7 dias). A indicação foi reduzida para até 2 sessões, sem substituir orientação individual.</div>`:``}${dayCards}</div></div><p class="small muted">Sugestão geral: organize as sessões físicas em dias que permitam recuperação do jiu-jitsu. Os exercícios são exemplos educativos, não prescrição individual.</p>`;
}
function activeWorkoutDay(){
 const w=state.workout;if(!w)return null;
 if(w.day&&Array.isArray(w.day.ids)){const items=w.day.ids.map(id=>BY_ID[id]).filter(Boolean);return items.length?{title:w.day.title,items}:null;}
 return currentPlan().days[w.index]||null;
}
function renderWorkout(){
 const work=state.workout,day=activeWorkoutDay();
 if (!day) {state.workout=null;save();return renderPlan();}
 const done=Object.values(work.completed||{}).reduce((a,b)=>a+Number(b||0),0),total=day.items.reduce((a,e)=>a+e.sets,0);
 return `${header('Sessão em andamento','Treino <span>em execução.</span>',esc(day.title))}
 <button class="back" data-action="leaveWorkout">← Voltar ao início (mantém sessão)</button>
 <div class="grid"><div class="span-8"><section class="card"><div class="row between"><h2 class="section-title">Cronômetro da sessão</h2><span class="badge">TEMPO REAL</span></div>
 <div class="timer-face" id="work-clock">00:00</div><p class="timer-caption" id="work-clock-label">Tempo de treino em andamento</p>
 <div class="timer-controls"><button class="btn secondary small-btn" data-action="workPause" id="work-pause">Pausar</button><button class="btn ghost small-btn" data-action="workResume">Retomar</button><button class="btn secondary small-btn" data-action="restStart">Descanso de 60 s</button><button class="btn ghost small-btn" data-action="restStop">Encerrar descanso</button></div>
 <p id="rest-countdown" class="small muted" style="margin-top:11px;text-align:center">Pausa opcional entre séries.</p>
 <div class="divider"></div><div class="row between"><h2 class="section-title">Checklist de séries</h2><span class="badge">${done}/${total} séries</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,done/Math.max(1,total)*100)}%"></div></div><p class="small muted">Marque as séries concluídas. A qualidade do movimento vale mais que o número de repetições.</p>
 ${day.items.map((ex,i)=>`<div class="session-step"><div class="exicon">${exIcon(ex)}</div><div class="exbody"><h3>${esc(ex.name)}</h3><p>${ex.sets} ${ex.sets===1?'série':'séries'} de ${esc(ex.dose)}</p><div class="count-pill"><button aria-label="Retirar série de ${esc(ex.name)}" data-action="setMinus" data-index="${i}">−</button><output id="sets-${i}">${work.completed?.[i]||0}</output><button aria-label="Adicionar série de ${esc(ex.name)}" data-action="setPlus" data-index="${i}">+</button><span class="small muted">de ${ex.sets} séries</span><button class="linklike" data-action="exercise" data-id="${ex.id}">Ver técnica</button></div></div></div>`).join('')}
 <div class="form-grid" style="margin-top:18px"><div class="field"><label for="work-duration">Tempo total (minutos)</label><input type="number" id="work-duration" min="1" max="300" value="${Math.max(1,Math.min(300,Math.ceil(activeMs()/60000)))}" required></div><div class="field"><label for="work-rpe">Esforço percebido</label><select id="work-rpe">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===5?'selected':''}>${i+1}/10</option>`).join('')}</select></div></div><div class="field" style="margin-top:12px"><label for="work-notes">Observações do treino</label><textarea id="work-notes" placeholder="Como foi? Algum desconforto ou dificuldade?"></textarea></div><div class="session-actions"><button class="btn" data-action="finishWorkout">Salvar sessão</button><button class="btn ghost" data-action="cancelWorkout">Cancelar sessão</button></div></section></div><div class="span-4">${section('Orientações',`<p class="small muted">Realize movimentos de forma controlada. Utilize pausas conforme necessidade e evite falhar deliberadamente em todas as séries.</p><div class="note warn">Em caso de dor aguda, tontura, falta de ar incomum ou mal-estar, interrompa o treino. Não registre exercício não realizado como concluído.</div>`)}</div></div>`;
}
function renderExerciseDetail(ex){return `<button class="back" data-action="backExercise">← Voltar</button>${header('Biblioteca de movimentos',`${esc(ex.name)}`,'Descrição educativa de execução e atenção à técnica.')}
 <div class="grid"><div class="span-7">${section('Como executar',`${imagesHtml(ex)}${bjjDiagram(ex)}${visualGuide(ex)}${!remoteImages(ex)&&!bjjDiagram(ex)&&!visualGuide(ex)?`<div class="note warn" style="margin-bottom:13px">Ainda não existe demonstração visual verificada deste movimento. Não execute apenas pela descrição escrita: peça orientação ao professor ou treinador.</div>`:""}<div class="pill-row">${chip(tagCat(ex))}${chip(LABELS.gear[ex.gear])}${chip('Nível '+(ex.level===1?'básico':ex.level===2?'intermediário':'avançado'))}</div><p class="lead">${esc(ex.why)}</p><ol style="padding-left:22px">${ex.steps.map(s=>`<li style="margin:10px 0">${esc(s)}</li>`).join('')}</ol><div class="note warn"><strong>Atenção:</strong> ${esc(ex.caution)}</div>`)}</div><div class="span-5">${section('Dose inicial sugerida',`<div class="kpi">${ex.sets} <span style="font-size:15px;font-weight:650">séries</span></div><p>${esc(ex.dose)}</p><p class="small muted">Ajuste conforme a técnica, esforço e recuperação. Essa dose não é individualizada.</p>`)}</div></div>`;}
function renderCatalogList(){
 const q=search.trim().toLocaleLowerCase('pt-BR');const found=EXERCISES.filter(e=>(filter==='todos'||e.category===filter) && (e.name.toLocaleLowerCase('pt-BR').includes(q)||e.focus.join(' ').includes(q)||e.why.toLocaleLowerCase('pt-BR').includes(q)));
 return `<div class="row between"><span class="small muted">${found.length} exercícios encontrados</span><span class="badge gray">Catálogo próprio</span></div>${found.map(e=>exRow(e)).join('')||'<div class="empty">Nenhum exercício corresponde à pesquisa.</div>'}`;
}
function renderExercises(){if(selectedTech&&TECH_BY_ID[selectedTech])return renderTechDetail(TECH_BY_ID[selectedTech]);if(selectedExercise)return renderExerciseDetail(BY_ID[selectedExercise]);if(libMode==='tecnicas')return renderTechniques();return `${header('Biblioteca de movimentos','Cada exercício tem <span>um propósito.</span>','Fotos de referência quando disponíveis, instruções e cuidados. Drills sem imagem verificada são identificados.')}${libToggle()}
 <section class="card"><div class="form-grid"><div class="field"><label for="search-ex">Buscar exercício</label><input id="search-ex" type="search" placeholder="Ex.: pegada, prancha, quadril..." value="${esc(search)}" autocomplete="off"></div><div class="field"><label for="filter-ex">Tipo de exercício</label><select id="filter-ex"><option value="todos">Todas as categorias</option>${options(LABELS.category,filter)}</select></div></div><div class="divider"></div><div id="catalog-list">${renderCatalogList()}</div></section>`;}

function timerHtml(){return `<section class="card" id="timer-card"><div class="row between"><div><div class="eyebrow">Timer BJJ</div><h2 class="card-title" style="margin-top:7px">Rounds e descanso</h2></div><span class="badge gray" id="timer-stage">PRONTO</span></div><div class="form-grid" style="margin:12px 0"><div class="field"><label for="round-min">Duração de cada round</label><select id="round-min">${[2,3,4,5,6,8,10].map(v=>`<option value="${v}" ${v===5?'selected':''}>${v} min</option>`).join('')}</select></div><div class="field"><label for="rest-sec">Descanso entre rounds</label><select id="rest-sec">${[15,30,45,60,90,120].map(v=>`<option value="${v}" ${v===60?'selected':''}>${v} s</option>`).join('')}</select></div><div class="field"><label for="round-count">Quantidade de rounds</label><select id="round-count">${[1,2,3,4,5,6,8,10].map(v=>`<option value="${v}" ${v===5?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Áudio</label><div class="field-output small">Aviso sonoro quando permitido</div></div></div><div class="timer-face" id="timer-face">05:00</div><div class="timer-caption" id="timer-caption">Round 1 de 5</div><div class="timer-controls" style="margin-top:20px"><button class="btn" data-action="timerStart" id="timer-start">Iniciar</button><button class="btn secondary" data-action="timerPause">Pausar</button><button class="btn ghost" data-action="timerReset">Reiniciar</button></div><p class="tiny muted" style="margin-top:17px">O cronômetro usa o relógio do aparelho para compensar atrasos de tela; o som pode não funcionar com o navegador em segundo plano.</p></section>`;}
function renderDiary(){return `${header('Jiu-jitsu no cotidiano','Seu <span>diário de tatame.</span>','Registre aulas, rolas, temas e esforço. Depois o app conecta esse volume aos treinos físicos.')}
 <div class="grid"><div class="span-6"><section class="card"><h2 class="section-title">Registrar treino de BJJ</h2><form id="bjj-form" class="stack"><div class="form-grid"><div class="field"><label for="bjj-date">Data</label><input id="bjj-date" name="date" type="date" value="${isoLocalDate()}" required></div><div class="field"><label for="bjj-duration">Duração em minutos</label><input id="bjj-duration" name="duration" type="number" min="1" max="300" value="60" required></div><div class="field"><label for="bjj-rounds">Quantidade de rolas</label><input id="bjj-rounds" name="rounds" type="number" min="0" max="30" value="3" required></div><div class="field"><label for="bjj-rpe">Intensidade percebida (1 a 10)</label><select id="bjj-rpe" name="rpe">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===5?'selected':''}>${i+1}/10</option>`).join('')}</select></div></div><div class="field"><label for="bjj-focus">Tema principal</label><select id="bjj-focus" name="focus"><option>Guarda e raspagens</option><option>Passagem de guarda</option><option>Quedas</option><option>Defesas e fugas</option><option>Finalizações</option><option>Treino livre</option></select></div>${diaryTechFields()}<div class="field"><label for="bjj-note">Anotações técnicas</label><textarea id="bjj-note" name="note" maxlength="1000" placeholder="O que funcionou? O que gostaria de melhorar?"></textarea></div><button class="btn" type="submit">Salvar treino de jiu-jitsu</button></form></section></div>
 <div class="span-6">${timerHtml()}</div><div class="span-12">${section('Seus treinos recentes',latestHistory(12))}</div></div>`;}
function weeksChart(){
 const now=new Date();now.setHours(12,0,0,0);const day=now.getDay();now.setDate(now.getDate()-(day===0?6:day-1));const weeks=[];
 for(let i=5;i>=0;i--){const start=new Date(now);start.setDate(start.getDate()-i*7);const end=new Date(start);end.setDate(end.getDate()+7);const total=state.history.filter(s=>{const d=new Date(s.date+'T12:00:00');return d>=start && d<end;}).reduce((a,s)=>a+(Number(s.duration)||0),0);weeks.push({label:fmtDate(isoLocalDate(start)),total});}
 const max=Math.max(30,...weeks.map(x=>x.total));return `<div class="bar-plot">${weeks.map(w=>`<div class="bar-col"><span class="tiny muted">${w.total?`${w.total}m`:''}</span><div class="bar" style="height:${Math.max(3,(w.total/max)*117)}px" title="${w.total} minutos"></div><small>${w.label}</small></div>`).join('')}</div>`;
}
function renderProgress(){const stats=summarize(state.history),week=recent(7);const physical=state.history.filter(s=>s.type==='fisico');const completed=physical.reduce((n,s)=>n+(s.items||[]).reduce((k,item)=>k+(Number(item.done)||0),0),0);return `${header('Acompanhe sua jornada','Evolução <span>sem achismo.</span>','Aqui você acompanha o volume registrado. Progresso técnico no tatame também depende de prática e orientação.')}
 <div class="grid"><div class="span-3"><div class="stat"><div class="kpi">${stats.bjj}</div><div class="kpi-label">Treinos BJJ · 30 dias</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${stats.physical}</div><div class="kpi-label">Treinos físicos · 30 dias</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${stats.minutes}</div><div class="kpi-label">Minutos · 30 dias</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${stats.rounds}</div><div class="kpi-label">Rolas · 30 dias</div></div></div>
 <div class="span-7">${section('Volume nas últimas 6 semanas',weeksChart()+`<div class="row between" style="margin-top:18px"><span class="small muted">Tempo registrado: treinos físicos + BJJ</span><span class="badge gray">Minutos</span></div>`)}</div>
 <div class="span-5">${section('Resumo da prática',`<div class="stack"><div class="result"><div class="muted small">Séries físicas registradas (total)</div><strong style="font-size:28px">${completed}</strong></div><div class="result"><div class="muted small">Dias com registros nos últimos 7 dias</div><strong style="font-size:28px">${new Set(week.map(s=>s.date)).size}</strong></div></div><p class="small muted">Acompanhe regularidade sem transformar descanso em competição.</p>`)}</div>
 ${bjjTechSection()}<div class="span-12">${section('Evolução por habilidade',`<p class="small muted">${skillCompleted(state.skills)} etapas registradas em ${TRACKS.length} trilhas. Registre domínio sem pular a técnica.</p><button class="btn secondary small-btn" data-action="navigate" data-to="habilidades">Abrir progressões →</button>`)}</div><div class="span-12">${section('Histórico completo',latestHistory(100))}</div></div>`;}
function renderSkills(){
 const done=skillCompleted(state.skills),total=TRACKS.reduce((a,t)=>a+t.stages.length,0),profile=state.profile;
 if(selectedTrack){
  const track=TRACKS.find(t=>t.id===selectedTrack);if(!track){selectedTrack=null;return renderSkills();}
  const ix=skillIndex(state.skills,track),stage=track.stages[ix],ex=stage?BY_ID[stage.id]:null;
  const allowed=ex&&stageAllowed(ex,profile);
  return `<button class="back" data-action="skillsBack">← Todas as trilhas</button>${header('Habilidades para o tatame',esc(track.title),esc(track.subtitle))}
  <div class="grid"><div class="span-7"><section class="card"><h2 class="section-title">Sua sequência</h2><div class="skill-steps">${track.stages.map((s,i)=>`<div class="skill-step ${i<ix?'done':i===ix?'current':''}"><span class="skill-count">${i<ix?'✓':i+1}</span><div><strong>${esc(BY_ID[s.id].name)}</strong><p class="small muted">${i<ix?'Etapa registrada':i===ix?'Etapa atual':'Próxima etapa'} · ${esc(LABELS.gear[BY_ID[s.id].gear])}</p></div>${i===ix?'<span class="badge">AGORA</span>':''}</div>`).join('')}</div></section></div>
  <div class="span-5"><section class="card"><h2 class="section-title">${ix>=track.stages.length?'Trilha concluída':'Etapa atual'}</h2>${stage?`<p><strong>${esc(ex.name)}</strong></p><p class="small muted">Meta orientativa: ${esc(stage.criterion)}</p><p class="small muted">Séries registradas deste exercício: ${recordedSets(state.history,ex.id)}</p>${allowed?`<div class="stack"><label class="toggle-line"><input type="checkbox" id="skill-check1"> <span>Completei a meta com técnica controlada.</span></label><label class="toggle-line"><input type="checkbox" id="skill-check2"> <span>Não tive dor nem perda de controle.</span></label><button class="btn" data-action="skillNext" data-id="${track.id}">Registrar domínio desta etapa</button></div>`:`<div class="note warn">Esta etapa não está disponível com seu nível, equipamentos ou opção de cautela atuais. Ajuste o perfil e priorize segurança.</div>`}<button class="btn ghost small-btn" data-action="exercise" data-id="${ex.id}">Ver execução →</button>`:`<p>Você registrou todas as etapas desta trilha. Continue treinando com qualidade, sem obrigação de aumentar dificuldade.</p>`}${ix>0?`<div class="divider"></div><button class="btn ghost small-btn" data-action="skillBackStep" data-id="${track.id}">Corrigir etapa anterior</button>`:''}</section></div></div>
  <p class="small muted" style="margin-top:18px">Estas metas são referências educativas, não avaliação de capacidade, técnica de luta ou diagnóstico. Progredir requer domínio, ausência de sintomas e recuperação suficiente.</p>`;
 }
 return `${header('Seu mapa de habilidades','Progrida com <span>critério.</span>','Evolução por qualidade de movimento. Avançar é uma decisão consciente, nunca automática.')}
 <section class="card"><div class="row between"><div><div class="eyebrow">Seu progresso</div><strong>${done} de ${total} etapas registradas</strong></div><span class="badge gray">v0.2</span></div><div class="progress-track" style="margin-top:12px"><div class="progress-fill" style="width:${Math.round(100*done/total)}%"></div></div><p class="tiny muted">Metas não são obrigatórias nem representam graduação no jiu-jitsu.</p></section><div class="grid" style="margin-top:14px">${TRACKS.map(t=>{const ix=skillIndex(state.skills,t),stage=t.stages[ix],ex=stage?BY_ID[stage.id]:null;return `<div class="span-6"><section class="card skill-card"><span class="badge gray">${ix}/${t.stages.length} etapas</span><h2 class="card-title" style="margin-top:10px">${esc(t.title)}</h2><p class="small muted">${esc(t.subtitle)}</p><p><strong>Agora:</strong> ${ex?esc(ex.name):'Trilha registrada'}</p><button class="btn secondary small-btn" data-action="skillView" data-id="${t.id}">Abrir trilha →</button></section></div>`;}).join('')}</div>`;
}
