function renderTechniques(){const s=techniqueSummary(state.techniques);return `${header('Biblioteca de técnicas','Seu <span>mapa do tatame.</span>','Marque o que você já viu, o que está drilando e o que já funciona no rola. Quem ensina a técnica é o professor; aqui fica o seu mapa de estudo.')}${libToggle()}
 <div class="grid" style="margin-bottom:15px">${[3,2,1,0].map(k=>`<div class="span-3"><div class="stat"><div class="kpi">${s.counts[k]}</div><div class="kpi-label">${esc(TECH_STATUS[k])}</div></div></div>`).join('')}</div>
 <section class="card"><div class="form-grid"><div class="field"><label for="tech-search">Buscar técnica</label><input id="tech-search" type="search" placeholder="Ex.: armlock, meia-guarda, montada..." value="${esc(techQuery)}" autocomplete="off"></div><div class="field"><label for="tech-cat">Categoria</label><select id="tech-cat"><option value="todas">Todas</option>${options(TECH_CATEGORIES,techCat)}</select></div><div class="field"><label for="tech-status">Mostrar</label><select id="tech-status">${options({todos:'Todas',foco:'Só em foco',3:TECH_STATUS[3],2:TECH_STATUS[2],1:TECH_STATUS[1],0:TECH_STATUS[0]},String(techStatusFilter))}</select></div></div><div class="divider"></div><div id="tech-list">${renderTechList()}</div></section>`;}
function renderTechDetail(t){const st=techniqueStatus(state.techniques,t.id),cur=state.techniques[t.id]||{},h=techniqueHistory(state.history,t.id),def=DEFENSE[t.id]?TECH_BY_ID[DEFENSE[t.id]]:null;
 return `<button class="back" data-action="techBack">← Voltar</button>${header(TECH_CATEGORIES[t.cat],esc(t.name),`${esc(t.from)} · ${esc(TECH_LEVELS[t.level])} · ${esc(TECH_GI[t.gi])}`)}
 <div class="grid"><div class="span-7">${section('Pontos-chave',`<ol style="padding-left:22px;margin-top:4px">${t.points.map(x=>`<li style="margin:10px 0">${esc(x)}</li>`).join('')}</ol>${t.cat==='finalizacao'?'<div class="note warn"><strong>Segurança:</strong> aplique devagar e solte no primeiro tapinha. Treine com parceiro e com o professor por perto.</div>':''}${def?`<div class="note" style="margin-top:12px">Se você sofre muito esta finalização, estude também: <button class="linklike" data-action="techView" data-id="${def.id}">${esc(def.name)} →</button></div>`:''}<div class="row wrap" style="margin-top:15px"><a class="btn secondary" href="${videoSearchUrl(t)}" target="_blank" rel="noopener noreferrer">Ver vídeos no YouTube ↗</a></div><p class="tiny muted" style="margin-top:8px">Abre uma busca no YouTube. Prefira vídeos de professores reconhecidos e confira com a sua academia.</p>`)}</div>
 <div class="span-5">${section('Seu domínio',`<div class="status-list">${[0,1,2,3].map(k=>`<button class="status-btn ${st===k?'on':''}" data-action="techSetStatus" data-id="${t.id}" data-status="${k}" aria-pressed="${st===k}"><span class="badge st-${k}">${k}</span> ${esc(TECH_STATUS[k])}</button>`).join('')}</div><button class="btn ${cur.focus?'ghost':'secondary'}" style="width:100%;margin-top:12px" data-action="techFocus" data-id="${t.id}">${cur.focus?'Tirar do foco':'Colocar em foco'}</button>${cur.updated?`<p class="tiny muted" style="margin-top:8px">Atualizado em ${fmtDate(cur.updated)}</p>`:''}<div class="divider"></div><div class="stack small"><div class="row between"><span class="muted">Treinada em aula (diário)</span><strong>${h.worked}×</strong></div>${t.cat==='finalizacao'?`<div class="row between"><span class="muted">Você aplicou</span><strong>${h.given}×</strong></div><div class="row between"><span class="muted">Você sofreu</span><strong>${h.taken}×</strong></div>`:''}</div>`)}
 <section class="card" style="margin-top:15px"><h2 class="section-title">Suas anotações</h2><form id="tech-note-form" data-id="${t.id}" class="stack"><div class="field"><label for="tech-note">Detalhes que o professor corrigiu, ajustes que funcionaram</label><textarea id="tech-note" name="note" maxlength="500" placeholder="Ex.: manter o joelho colado; pegada na manga antes de girar.">${esc(cur.note||'')}</textarea></div><button class="btn" type="submit">Salvar anotação</button></form></section></div></div>`;}
function chipsHtml(k){return diaryDraft[k].map((id,i)=>`<button type="button" class="chip removable" data-action="pickRemove" data-picker="${k}" data-index="${i}" aria-label="Remover ${esc(techName(id))}">${esc(techName(id))} ✕</button>`).join('')||'<span class="tiny muted">Nenhuma adicionada.</span>';}
function refreshChips(k){const el=document.getElementById('chips-'+k);if(el)el.innerHTML=chipsHtml(k);}
function pickerHtml(k,label,opts){return `<div class="field"><label for="pick-${k}">${label}</label><div class="row" style="gap:8px"><select id="pick-${k}" style="flex:1;min-width:0">${opts}</select><button type="button" class="btn secondary small-btn" data-action="pickAdd" data-picker="${k}">+ Adicionar</button></div><div class="pill-row" id="chips-${k}" style="margin-top:8px">${chipsHtml(k)}</div></div>`;}
function diaryTechFields(){return `<div class="field"><label for="bjj-kind">Tipo de aula</label><select id="bjj-kind" name="kind">${options(SESSION_KINDS,'kimono')}</select></div>
 <div class="form-grid three"><div class="field"><label for="bjj-sweeps">Raspagens</label><input id="bjj-sweeps" name="sweeps" type="number" min="0" max="50" value="0"></div><div class="field"><label for="bjj-passes">Passagens</label><input id="bjj-passes" name="passes" type="number" min="0" max="50" value="0"></div><div class="field"><label for="bjj-takedowns">Quedas</label><input id="bjj-takedowns" name="takedowns" type="number" min="0" max="50" value="0"></div></div>
 ${pickerHtml('given','Finalizações que você aplicou nos rolas',SUB_OPTIONS)}${pickerHtml('taken','Finalizações que você sofreu',SUB_OPTIONS)}${pickerHtml('worked','Técnicas ensinadas ou drilladas na aula',ALL_TECH_OPTIONS)}
 <fieldset class="field plain"><legend>Onde você mais sofreu hoje?</legend><div class="pill-row">${Object.entries(TROUBLE_SPOTS).map(([k,v])=>`<label class="check-chip"><input type="checkbox" name="trouble" value="${k}"><span>${esc(v.label)}</span></label>`).join('')}</div></fieldset>`;}
function bjjTechSection(){const st=bjjStats(state.history,30),ts=techniqueSummary(state.techniques);
 const list=(arr,empty,fn)=>arr.length?arr.map(fn).join(''):`<div class="empty small">${empty}</div>`;
 return `<div class="span-12">${section('Jiu-jitsu técnico · 30 dias',`<div class="grid"><div class="span-3"><div class="stat"><div class="kpi">${st.given}</div><div class="kpi-label">Finalizações aplicadas</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${st.taken}</div><div class="kpi-label">Finalizações sofridas</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${st.sweeps}</div><div class="kpi-label">Raspagens</div></div></div><div class="span-3"><div class="stat"><div class="kpi">${st.passes}</div><div class="kpi-label">Passagens</div></div></div></div>${st.roundsTracked?`<p class="small muted" style="margin-top:12px">Média de ${(st.given/st.roundsTracked).toFixed(1).replace('.',',')} finalizações aplicadas e ${(st.taken/st.roundsTracked).toFixed(1).replace('.',',')} sofridas por rola (só treinos com finalizações registradas).</p>`:''}`)}</div>
 <div class="span-4">${section('O que funciona para você',list(st.topGiven,'Registre as finalizações no diário.',x=>`<div class="row between rank"><span>${esc(techName(x.id))}</span><strong>${x.n}×</strong></div>`))}</div>
 <div class="span-4">${section('O que mais te pega',list(st.topTaken,'Nenhuma finalização sofrida registrada.',x=>{const d=DEFENSE[x.id];return `<div class="rank"><div class="row between"><span>${esc(techName(x.id))}</span><strong>${x.n}×</strong></div>${d?`<button class="linklike" data-action="techView" data-id="${d}">Estudar: ${esc(TECH_BY_ID[d].name)} →</button>`:''}</div>`;}))}</div>
 <div class="span-4">${section('Onde você mais sofre',list(st.trouble,'Marque no diário onde você sofreu.',x=>{const t=TROUBLE_SPOTS[x.id];return `<div class="rank"><div class="row between"><span>${esc(t?.label||x.id)}</span><strong>${x.n}×</strong></div>${t?.study?`<button class="linklike" data-action="techView" data-id="${t.study}">Estudar: ${esc(TECH_BY_ID[t.study].name)} →</button>`:t?`<button class="linklike" data-action="navigate" data-to="plano">Ver plano físico →</button>`:''}</div>`;}))}</div>
 <div class="span-6">${section('Domínio técnico',`<p><strong>${ts.counts[3]}</strong> de ${ts.total} técnicas funcionam no rola · <strong>${ts.counts[2]}</strong> drilando</p><div class="progress-track"><div class="progress-fill" style="width:${Math.round(100*ts.counts[3]/ts.total)}%"></div></div><button class="btn secondary small-btn" style="margin-top:12px" data-action="openLib">Abrir biblioteca →</button>`)}</div>
 <div class="span-6">${beltCard()}</div>`;}
function renderBelt(){const b=beltStats(state.belt,state.history,state.profile.belt),promos=sortedPromotions(state.belt).reverse(),next=b.nextBelt?BELTS[b.nextBelt]:null,goals=state.belt.goals;
 const ibjjf=b.belt==='branca'?'<p class="small muted">A IBJJF não exige tempo mínimo na faixa branca. A graduação depende do seu professor.</p>':b.minMonths&&next?(b.beltSince?`<div class="row between" style="margin-top:6px"><span class="small muted">Tempo mínimo IBJJF para a ${esc(next.label.toLowerCase())}: ${b.minMonths>=12&&b.minMonths%12===0?b.minMonths/12+' '+(b.minMonths===12?'ano':'anos'):b.minMonths+' meses'}</span><strong class="small">${Math.round(b.minProgress*100)}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round(b.minProgress*100)}%"></div></div><p class="tiny muted">Referência para atletas adultos (18+). Tempo mínimo não é promoção automática: quem decide é o professor.</p>`:'<p class="small muted">Registre a data em que recebeu esta faixa para ver o tempo mínimo de referência da IBJJF.</p>'):'';
 return `${header('Graduação','Sua <span>jornada de faixa.</span>','Faixa, graus, tempo e treinos desde a última graduação. Quem gradua é o seu professor; aqui você acompanha.')}
 <div class="grid"><div class="span-7"><section class="card">${beltBar(b.belt,b.degrees,true)}<h2 class="card-title" style="margin-top:14px">${esc(b.info.label)} · ${b.degrees} ${b.degrees===1?'grau':'graus'}</h2><div class="stack small" style="margin-top:10px"><div class="row between"><span class="muted">Nesta faixa há</span><strong>${formatDuration(b.daysInBelt)}</strong></div><div class="row between"><span class="muted">Desde a última graduação</span><strong>${formatDuration(b.daysSinceDegree)}</strong></div><div class="row between"><span class="muted">Treinos desde a última graduação</span><strong>${b.sessionsSinceDegree}</strong></div><div class="row between"><span class="muted">Horas de tatame desde a última graduação</span><strong>${b.hoursSinceDegree} h</strong></div><div class="row between"><span class="muted">Treinos nesta faixa</span><strong>${b.sessionsInBelt}</strong></div></div><div class="divider"></div>${ibjjf}</section></div>
 <div class="span-5"><section class="card"><h2 class="section-title">Registrar graduação</h2><p class="small muted">Registre cada grau e cada faixa nova. Comece pela sua graduação atual, com a data aproximada.</p><form id="promo-form" class="stack"><div class="form-grid"><div class="field"><label for="promo-date">Data</label><input id="promo-date" name="date" type="date" value="${isoLocalDate()}" max="${isoLocalDate()}" required></div><div class="field"><label for="promo-belt">Faixa</label><select id="promo-belt" name="belt">${options(Object.fromEntries(Object.entries(BELTS).map(([k,v])=>[k,v.label])),b.belt)}</select></div><div class="field"><label for="promo-degrees">Graus</label><select id="promo-degrees" name="degrees">${[0,1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===Math.min(b.degrees+(promos.length?1:0),BELTS[b.belt].maxDegrees)?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="promo-note">Observação</label><input id="promo-note" name="note" maxlength="200" placeholder="Ex.: graduado pelo prof. ..."></div></div><button class="btn" type="submit">Salvar graduação</button></form></section></div>
 <div class="span-12">${section('Histórico de graduações',promos.length?promos.map(p=>`<div class="history-item"><div style="width:72px;flex:none">${beltBar(p.belt,p.degrees)}</div><div class="meta"><h4>${esc(BELTS[p.belt].label)} · ${p.degrees} ${p.degrees===1?'grau':'graus'}</h4><p>${fmtDate(p.date)} de ${p.date.slice(0,4)}${p.note?' · '+esc(p.note):''}</p></div><button class="linklike" data-action="promoDelete" data-id="${esc(p.id)}" aria-label="Apagar registro">Apagar</button></div>`).join(''):'<div class="empty">Nenhuma graduação registrada ainda.</div>')}</div>
 <div class="span-7">${section('Metas técnicas',`<p class="small muted">Metas que você combinou com o professor ou definiu para a próxima graduação.</p>${goals.length?goals.map(g=>`<div class="goal ${g.done?'done':''}"><label class="toggle-line" style="margin:0;flex:1"><input type="checkbox" data-action="goalToggle" data-id="${esc(g.id)}" ${g.done?'checked':''}> <span>${esc(g.text)}</span></label><button class="linklike" data-action="goalDelete" data-id="${esc(g.id)}" aria-label="Apagar meta">✕</button></div>`).join(''):'<div class="empty small">Nenhuma meta ainda.</div>'}<form id="goal-form" class="row" style="margin-top:12px;gap:8px"><input class="inline-input" name="text" maxlength="120" placeholder="Ex.: fugir da montada contra faixas azuis" required><button class="btn small-btn" type="submit">Adicionar</button></form>`)}</div>
 <div class="span-5">${section('Frequência mensal',`<form id="monthly-form" class="stack"><div class="field"><label for="monthly-goal">Meta de treinos de BJJ por mês</label><select id="monthly-goal" name="goal">${[0,4,8,12,16,20,24].map(n=>`<option value="${n}" ${n===state.belt.monthlyGoal?'selected':''}>${n?n+' treinos':'Sem meta'}</option>`).join('')}</select></div><button class="btn secondary small-btn" type="submit">Salvar meta</button></form>${monthGoalHtml()}`)}</div></div>
 <p class="small muted" style="margin-top:16px">Referência de tempo mínimo: Sistema Geral de Graduação da IBJJF (adultos). Cada academia e federação pode ter critérios próprios.</p>`;}

function render(){document.querySelectorAll('[data-tab]').forEach(n=>{n.classList.toggle('selected',n.dataset.tab===(['habilidades','rotina','faixa'].includes(tab)?'evolucao':tab));n.setAttribute('aria-current',n.dataset.tab===(['habilidades','rotina','faixa'].includes(tab)?'evolucao':tab)?'page':'false');});content.innerHTML=tab==='inicio'?renderHome():tab==='plano'?renderPlan():tab==='exercicios'?renderExercises():tab==='diario'?renderDiary():tab==='evolucao'?renderProgress():tab==='habilidades'?renderSkills():tab==='rotina'?renderRoutine():tab==='faixa'?renderBelt():renderSettings(); if(tab==='diario')syncTimerUI();}

// Temporizador resiste a atrasos de execução por meio de timestamps reais.
let timer={running:false,started:false,phase:'round',round:1,total:5,roundMs:300000,restMs:60000,remainingMs:300000,endAt:0,done:false};
let audioCtx;
function beep(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioCtx=audioCtx||new Audio();const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain();oscillator.type='sine';oscillator.frequency.value=740;gain.gain.value=.05;oscillator.connect(gain);gain.connect(audioCtx.destination);oscillator.start();oscillator.stop(audioCtx.currentTime+.16);if(navigator.vibrate)navigator.vibrate(100);}catch{}}
function timerSetup(){const r=Number(document.getElementById('round-min')?.value||5),rest=Number(document.getElementById('rest-sec')?.value||60),count=Number(document.getElementById('round-count')?.value||5);timer={running:false,started:false,phase:'round',round:1,total:count,roundMs:r*60000,restMs:rest*1000,remainingMs:r*60000,endAt:0,done:false};syncTimerUI();}
function timerTick(){if(!timer.running)return;let safety=0;while(timer.running&&Date.now()>=timer.endAt&&safety++<100){if(timer.phase==='round'){if(timer.round>=timer.total){timer.running=false;timer.done=true;timer.remainingMs=0;break;}timer.phase='rest';timer.endAt+=timer.restMs;}else{timer.phase='round';timer.round++;timer.endAt+=timer.roundMs;}beep();}if(timer.running)timer.remainingMs=Math.max(0,timer.endAt-Date.now());syncTimerUI();}
function syncTimerUI(){const face=document.getElementById('timer-face');if(!face)return;const r=timer.started?timer.remainingMs:Number(document.getElementById('round-min')?.value||5)*60000;const secs=Math.ceil(r/1000),m=String(Math.floor(secs/60)).padStart(2,'0'),s=String(secs%60).padStart(2,'0');face.textContent=`${m}:${s}`;face.classList.toggle('rest',timer.phase==='rest');document.getElementById('timer-stage').textContent=timer.done?'CONCLUÍDO':timer.started?(timer.phase==='round'?'ROUND':'DESCANSO'):'PRONTO';document.getElementById('timer-caption').textContent=timer.done?'Sessão finalizada':`Round ${timer.round} de ${timer.total}`;document.getElementById('timer-start').textContent=timer.running?'Executando...':timer.started?'Continuar':'Iniciar';document.getElementById('timer-start').disabled=timer.running||timer.done;}
setInterval(timerTick,250);
setInterval(sessionTick,350);
setInterval(reminderCheck,30000);

document.querySelector('.bottom-nav').addEventListener('click',e=>{const item=e.target.closest('[data-tab]');if(item)go(item.dataset.tab);});
document.getElementById('settings-shortcut').addEventListener('click',()=>go('ajustes'));
content.addEventListener('input',e=>{
 if(e.target.id==='tech-search'){techQuery=e.target.value;const l=document.getElementById('tech-list');if(l)l.innerHTML=renderTechList();}
 if(e.target.id==='search-ex'){search=e.target.value;const list=document.getElementById('catalog-list');if(list)list.innerHTML=renderCatalogList();}
 if(e.target.id==='readiness'){document.getElementById('readiness-text').textContent=e.target.value+'/5';}
 if(e.target.id==='work-duration')e.target.dataset.userEdited='true';
});
content.addEventListener('change',e=>{
 if(e.target.id==='tech-cat'||e.target.id==='tech-status'){if(e.target.id==='tech-cat')techCat=e.target.value;else techStatusFilter=e.target.value;const l=document.getElementById('tech-list');if(l)l.innerHTML=renderTechList();}
 if(e.target.id==='filter-ex'){filter=e.target.value;document.getElementById('catalog-list').innerHTML=renderCatalogList();}
 if(e.target.id==='readiness'){state.profile.readiness=Number(e.target.value);save();render();}
 if(e.target.id==='round-min'&&!timer.started){timerSetup();}
 if((e.target.id==='rest-sec'||e.target.id==='round-count')&&!timer.started){timerSetup();}
 if(e.target.id==='file-import'&&e.target.files[0]){const f=e.target.files[0];if(f.size>5_000_000){notify('Backup muito grande (máximo 5 MB).');return;}f.text().then(raw=>{let data;try{data=JSON.parse(raw)}catch{notify('Arquivo JSON inválido.');return;}if(!validateImport(data)){notify('Backup incompatível ou inválido.');return;}if(!confirm('Substituir o histórico e o perfil atuais por este backup?'))return;state={...freshState(),...data,profile:{...DEFAULT_PROFILE,...data.profile},reminders:normalizeReminders(data.reminders),belt:normalizeBelt(data.belt),techniques:data.techniques||{},workout:null};save();notify('Backup restaurado.');go('inicio');}).catch(()=>notify('Não foi possível ler o arquivo.'));}
});
content.addEventListener('submit',e=>{
 e.preventDefault();
 if(e.target.id==='routine-form'){
  const f=new FormData(e.target),days=f.getAll('day').map(Number),time=String(f.get('time')||'18:00'),duration=Number(f.get('duration')),waterInterval=Number(f.get('waterInterval'));
  if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)||days.some(n=>!Number.isInteger(n)||n<0||n>6)||!days.length){notify('Selecione ao menos um dia e um horário válido.');return;}
  state.reminders={...state.reminders,enabled:f.has('enabled'),water:f.has('water'),days,time,duration:Math.max(10,Math.min(180,duration||35)),waterInterval:[120,180,240].includes(waterInterval)?waterInterval:180,lastWorkout:'',lastWater:''};save();notify('Rotina salva. Para alertas com app fechado, use o Google Agenda.');render();return;
 }
 if(e.target.id==='promo-form'){
  const f=new FormData(e.target),date=String(f.get('date')),belt=String(f.get('belt')),degrees=Number(f.get('degrees')),note=String(f.get('note')||'').trim().slice(0,200);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>isoLocalDate()){notify('Informe uma data válida, que não seja no futuro.');return;}
  if(!BELTS[belt]){notify('Faixa inválida.');return;}
  if(!Number.isInteger(degrees)||degrees<0||degrees>BELTS[belt].maxDegrees){notify(`A faixa ${BELTS[belt].label.toLowerCase()} vai de 0 a ${BELTS[belt].maxDegrees} graus.`);return;}
  if(state.belt.promotions.length>=60){notify('Limite de registros atingido.');return;}
  state.belt.promotions.push({id:crypto.randomUUID?.()||String(Date.now()),date,belt,degrees,...(note?{note}:{})});syncProfileBelt();save();render();notify('Graduação registrada. Oss!');return;
 }
 if(e.target.id==='goal-form'){
  const text=String(new FormData(e.target).get('text')||'').trim().slice(0,120);if(!text)return;
  if(state.belt.goals.length>=30){notify('Máximo de 30 metas. Apague as concluídas.');return;}
  state.belt.goals.push({id:crypto.randomUUID?.()||String(Date.now()),text,done:false});save();render();return;
 }
 if(e.target.id==='monthly-form'){
  const n=Number(new FormData(e.target).get('goal'));if(!Number.isInteger(n)||n<0||n>31)return;state.belt.monthlyGoal=n;save();render();notify(n?`Meta: ${n} treinos por mês.`:'Meta mensal desativada.');return;
 }
 if(e.target.id==='tech-note-form'){
  const id=e.target.dataset.id;if(!TECH_BY_ID[id])return;const note=String(new FormData(e.target).get('note')||'').trim().slice(0,500);const cur=state.techniques[id]||{status:0};
  state.techniques[id]={...cur,status:techniqueStatus(state.techniques,id),updated:isoLocalDate(),...(note?{note}:{note:undefined})};if(!note)delete state.techniques[id].note;save();notify('Anotação salva.');return;
 }
 if(e.target.id==='profile-form'){
  const f=new FormData(e.target);state.profile={name:String(f.get('name')||'').trim().slice(0,48),belt:String(f.get('belt')),style:String(f.get('style')),goal:String(f.get('goal')),level:String(f.get('level')),equipment:String(f.get('equipment')),days:Math.min(3,Math.max(2,Number(f.get('days'))||2)),readiness:Math.min(5,Math.max(1,Number(f.get('readiness'))||3)),caution:f.has('caution')};syncProfileBelt();save();notify('Perfil atualizado.');go('plano');
 }
 if(e.target.id==='bjj-form'){
  const f=new FormData(e.target),duration=Number(f.get('duration')),rounds=Number(f.get('rounds')),rpe=Number(f.get('rpe')),date=String(f.get('date'));const cnt=k=>{const n=Number(f.get(k)||0);return Number.isInteger(n)&&n>=0&&n<=50?n:-1;},sweeps=cnt('sweeps'),passes=cnt('passes'),takedowns=cnt('takedowns');if(sweeps<0||passes<0||takedowns<0){notify('Raspagens, passagens e quedas: use números de 0 a 50.');return;}if(!Number.isInteger(rounds)||!Number.isInteger(duration)){notify('Use números inteiros em duração e rolas.');return;}
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||duration<1||duration>300||rounds<0||rounds>30||rpe<1||rpe>10){notify('Confira os dados do treino.');return;}
  const before=gamification(state.history,state.skills,state.profile.days).xp;state.history.push({id:crypto.randomUUID?.()||String(Date.now()),type:'bjj',date,duration,rounds,rpe,title:String(f.get('focus')).slice(0,80),note:String(f.get('note')||'').trim().slice(0,1000),kind:SESSION_KINDS[f.get('kind')]?String(f.get('kind')):'kimono',sweeps,passes,takedowns,given:[...diaryDraft.given],taken:[...diaryDraft.taken],worked:[...diaryDraft.worked],trouble:f.getAll('trouble').map(String).filter(k=>k in TROUBLE_SPOTS)});diaryDraft={given:[],taken:[],worked:[]};save();render();notify('BJJ registrado! +'+Math.max(0,gamification(state.history,state.skills,state.profile.days).xp-before)+' XP.');
 }
});

function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(x){return '"'+String(x??'').replace(/^[\s]*[=+@-]/,'\'$&').replace(/"/g,'""')+'"';}
content.addEventListener('click',e=>{
 const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action;
 if(action==='libMode'){libMode=btn.dataset.mode==='exercicios'?'exercicios':'tecnicas';selectedExercise=null;selectedTech=null;render();return;}
 if(action==='openLib'){libMode='tecnicas';go('exercicios');return;}
 if(action==='techView'){if(!TECH_BY_ID[btn.dataset.id])return;if(!selectedTech)techReturn=tab;selectedTech=btn.dataset.id;selectedExercise=null;libMode='tecnicas';tab='exercicios';render();window.scrollTo(0,0);return;}
 if(action==='techBack'){const r=techReturn;selectedTech=null;techReturn='exercicios';if(r==='exercicios'){render();window.scrollTo(0,0);}else go(r);return;}
 if(action==='techSetStatus'){const id=btn.dataset.id,st=Number(btn.dataset.status);if(!TECH_BY_ID[id]||![0,1,2,3].includes(st))return;state.techniques[id]={...(state.techniques[id]||{}),status:st,updated:isoLocalDate()};save();render();notify(`${TECH_BY_ID[id].name}: ${TECH_STATUS[st]}.`);return;}
 if(action==='techFocus'){const id=btn.dataset.id;if(!TECH_BY_ID[id])return;const cur=state.techniques[id]||{status:0};if(!cur.focus&&techniqueSummary(state.techniques).focus.length>=5){notify('Máximo de 5 técnicas em foco. Tire uma antes.');return;}state.techniques[id]={...cur,status:techniqueStatus(state.techniques,id),focus:!cur.focus};if(!state.techniques[id].focus)delete state.techniques[id].focus;save();render();return;}
 if(action==='pickAdd'){const k=btn.dataset.picker;if(!diaryDraft[k])return;const sel=document.getElementById('pick-'+k);const v=sel?.value;if(!v)return;if(diaryDraft[k].length>=30){notify('Limite de 30 itens por lista.');return;}if(k==='worked'&&diaryDraft[k].includes(v)){notify('Técnica já adicionada.');return;}diaryDraft[k].push(v);refreshChips(k);return;}
 if(action==='pickRemove'){const k=btn.dataset.picker,i=Number(btn.dataset.index);if(!diaryDraft[k])return;diaryDraft[k].splice(i,1);refreshChips(k);return;}
 if(action==='promoDelete'){if(!confirm('Apagar este registro de graduação?'))return;state.belt.promotions=state.belt.promotions.filter(p=>p.id!==btn.dataset.id);syncProfileBelt();save();render();return;}
 if(action==='goalToggle'){const g=state.belt.goals.find(x=>x.id===btn.dataset.id);if(g){g.done=!g.done;save();render();}return;}
 if(action==='goalDelete'){state.belt.goals=state.belt.goals.filter(x=>x.id!==btn.dataset.id);save();render();return;}
 if(action==='navigate'){if(btn.dataset.to==='habilidades')selectedTrack=null;go(btn.dataset.to);return;}
 if(action==='calendar'){const url=calendarUrl(state.reminders);if(!url){notify('Configure os dias e o horário antes.');return;}window.open(url,'_blank','noopener,noreferrer');return;}
 if(action==='calendarIcs'){const ics=calendarIcs(state.reminders);if(!ics){notify('Configure os dias e o horário antes.');return;}download('calistenia-bjj-treinos.ics',ics,'text/calendar;charset=utf-8');notify('Arquivo de calendário gerado.');return;}
 if(action==='notifications'){if(typeof Notification==='undefined'){notify('Este navegador não oferece notificações neste contexto. Use a Agenda.');return;}Notification.requestPermission().then(p=>{state.reminders.notify=p==='granted';save();notify(p==='granted'?'Avisos permitidos com app aberto.':'Notificações não foram permitidas. Use a Agenda.');}).catch(()=>notify('Não foi possível ativar os avisos.'));return;}
 if(action==='workPause'){const w=state.workout;if(w&&!w.paused){w.elapsedMs=activeMs();w.paused=true;save();sessionTick();}return;}
 if(action==='workResume'){const w=state.workout;if(w&&w.paused){w.resumeAt=Date.now();w.paused=false;save();sessionTick();}return;}
 if(action==='restStart'){const w=state.workout;if(w){w.restUntil=Date.now()+60000;save();sessionTick();}return;}
 if(action==='restStop'){const w=state.workout;if(w){w.restUntil=0;save();sessionTick();}return;}
 if(action==='skillView'){selectedTrack=btn.dataset.id;render();window.scrollTo(0,0);return;}
 if(action==='skillsBack'){selectedTrack=null;render();window.scrollTo(0,0);return;}
 if(action==='skillNext'){
  const track=TRACKS.find(t=>t.id===btn.dataset.id);if(!track)return;const ix=skillIndex(state.skills,track),ex=BY_ID[track.stages[ix]?.id];
  if(!ex||!stageAllowed(ex,state.profile)){notify('Esta etapa não está disponível neste perfil.');return;}
  if(!document.getElementById('skill-check1')?.checked||!document.getElementById('skill-check2')?.checked){notify('Confirme os dois critérios antes de avançar.');return;}
  if(!confirm('Registrar domínio desta etapa? Esta marcação é manual e não equivale a avaliação profissional.'))return;
  state.skills=state.skills||{};state.skills[track.id]=ix+1;save();render();notify('Etapa registrada! +40 XP.');return;
 }
 if(action==='skillBackStep'){
  const track=TRACKS.find(t=>t.id===btn.dataset.id);if(!track)return;const ix=skillIndex(state.skills,track);
  if(ix>0&&confirm('Voltar uma etapa desta trilha? Os treinos já registrados continuarão salvos.')){state.skills[track.id]=ix-1;save();render();}return;
 }

 if(action==='exercise'){exerciseReturn=tab;selectedExercise=btn.dataset.id;tab='exercicios';render();window.scrollTo(0,0);return;}
 if(action==='backExercise'){selectedExercise=null;go(exerciseReturn);return;}
 if(action==='startWorkout'){const idx=Number(btn.dataset.index),day=currentPlan().days[idx];if(!day)return;state.workout={index:idx,day:{title:day.title,ids:day.items.map(e=>e.id)},startedAt:Date.now(),resumeAt:Date.now(),elapsedMs:0,paused:false,restUntil:0,completed:{}};save();render();window.scrollTo(0,0);return;}
 if(action==='leaveWorkout'){go('inicio');return;}
 if(action==='cancelWorkout'){if(confirm('Descartar este treino sem salvá-lo?')){state.workout=null;save();render();}return;}
 if(action==='setPlus'||action==='setMinus'){
  const i=Number(btn.dataset.index),ex=activeWorkoutDay()?.items[i];if(!ex)return;
  const prior=Number(state.workout.completed[i]||0),next=Math.min(ex.sets,Math.max(0,prior+(action==='setPlus'?1:-1)));state.workout.completed[i]=next;save();const count=document.getElementById(`sets-${i}`);if(count)count.textContent=String(next);const day=activeWorkoutDay(),done=Object.values(state.workout.completed).reduce((n,v)=>n+Number(v||0),0),total=day.items.reduce((n,e)=>n+e.sets,0);const progress=document.querySelector('.progress-fill');if(progress)progress.style.width=Math.min(100,done/Math.max(1,total)*100)+'%';const countBadge=document.querySelector('.card .badge');if(countBadge)countBadge.textContent=`${done}/${total} séries`;return;
 }
 if(action==='finishWorkout'){
  if(!state.workout)return;const day=activeWorkoutDay();if(!day)return;const dur=Number(document.getElementById('work-duration')?.value),rpe=Number(document.getElementById('work-rpe')?.value),note=String(document.getElementById('work-notes')?.value||'').trim().slice(0,1000);
  const items=day.items.map((ex,i)=>({id:ex.id,name:ex.name,done:Number(state.workout.completed[i]||0),planned:ex.sets,dose:ex.dose}));
  if(!items.some(item=>item.done>0)){notify('Marque pelo menos uma série realizada.');return;}
  const record={id:crypto.randomUUID?.()||String(Date.now()),type:'fisico',date:isoLocalDate(),title:day.title,duration:dur,rpe,note,items,elapsedSeconds:Math.floor(activeMs()/1000)};
  if(!validateSession(record)||rpe<1||rpe>10){notify('Informe duração válida de 1 a 300 minutos.');return;}
  const before=gamification(state.history,state.skills,state.profile.days).xp;state.history.push(record);state.workout=null;save();go('evolucao');notify('Sessão salva! +'+Math.max(0,gamification(state.history,state.skills,state.profile.days).xp-before)+' XP.');return;
 }
 if(action==='export'){download(`calistenia-bjj-backup-${isoLocalDate()}.json`,JSON.stringify({...state,workout:null},null,2),'application/json');notify('Arquivo de backup gerado.');return;}
 if(action==='csv'){const head=['Data','Tipo','Título','Minutos','Rolas','Esforço 1-10','Notas','Tipo de aula','Finalizações aplicadas','Finalizações sofridas','Raspagens','Passagens','Quedas','Técnicas da aula'];const names=a=>(a||[]).map(techName).join(', ');const rows=state.history.map(s=>[s.date,s.type,s.title,s.duration,s.rounds||0,s.rpe,s.note||'',SESSION_KINDS[s.kind]||'',names(s.given),names(s.taken),s.sweeps??'',s.passes??'',s.takedowns??'',names(s.worked)]);download(`calistenia-bjj-historico-${isoLocalDate()}.csv`,[head,...rows].map(a=>a.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');notify('Histórico CSV gerado.');return;}
 if(action==='clear'){if(confirm('Apagar TODOS os registros e o perfil deste navegador? Essa ação não pode ser desfeita sem backup.')){state=freshState();save();notify('Dados apagados neste navegador.');go('inicio');}return;}
 if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>installPrompt=null);}else{notify('No Android: abra pelo Chrome, menu ⋮ e escolha “Adicionar à tela inicial” ou “Instalar app”.');}return;}
 if(action==='timerStart'){if(!timer.started)timerSetup();timer.started=true;timer.running=true;timer.endAt=Date.now()+timer.remainingMs;try{audioCtx?.resume?.();}catch{}syncTimerUI();return;}
 if(action==='timerPause'){if(timer.running){timerTick();timer.remainingMs=Math.max(0,timer.endAt-Date.now());timer.running=false;syncTimerUI();}return;}
 if(action==='timerReset'){timerSetup();return;}
});
